INSERT INTO `product_review` (review_id, spu_id, user_id, user_name, rating, content, images, is_mock, create_time) VALUES
(9100000000000000101, 9000000000000000010, 2107757313435291001, '跑者小周', 5, '鞋子很轻，透气性不错，跑了三公里脚感很好。', NULL, 1, '2026-09-20 10:15:00.000'),
(9100000000000000102, 9000000000000000010, 2107757313435291002, '晨跑一族', 5, '第二次买了，白色款颜值在线，尺码标准。', 'https://img.example.com/shoes1.jpg', 1, '2026-09-21 09:30:00.000'),
(9100000000000000103, 9000000000000000010, 2107757313435291003, '山野', 4, '整体不错，就是鞋底偏硬一点，穿久会适应。', NULL, 1, '2026-09-22 14:00:00.000'),
(9100000000000000104, 9000000000000000010, 2107757313435291004, 'lily2026', 5, '物流快，包装好，上脚舒服。', 'https://img.example.com/shoes2.jpg', 1, '2026-09-25 11:20:00.000'),
(9100000000000000105, 9000000000000000010, 2107757313435291005, '老张爱运动', 3, '尺码偏小半码，买之前最好买大一码，其他还行。', NULL, 1, '2026-09-27 16:45:00.000'),
(9100000000000000106, 9000000000000000010, 2107757313435291006, 'kobe24', 5, '性价比高，日常通勤跑步都合适。', NULL, 1, '2026-09-28 08:50:00.000'),
(9100000000000000107, 9000000000000000010, 2107757313435291007, '小徐', 2, '穿了半个月鞋头开胶了，质量一般，不太推荐。', 'https://img.example.com/shoes3.jpg', 1, '2026-09-30 19:10:00.000'),
(9100000000000000108, 9000000000000000010, 2107757313435291008, '夜跑侠', 5, '颜值高，黑色百搭，透气网面夏天穿不闷。', NULL, 1, '2026-10-02 07:40:00.000')
INSERT INTO `product_review` (review_id, spu_id, user_id, user_name, rating, content, images, is_mock, create_time) VALUES
(9100000000000000201, 9000000000000000011, 2107757313435291101, '通勤党', 5, '降噪效果超出预期，地铁上很安静，音质清晰。', 'https://img.example.com/earbuds1.jpg', 1, '2026-09-18 08:00:00.000'),
(9100000000000000202, 9000000000000000011, 2107757313435291102, '夜猫子', 4, '佩戴舒适，续航标称 4 小时实际 3 小时左右。', NULL, 1, '2026-09-19 12:30:00.000'),
(9100000000000000203, 9000000000000000011, 2107757313435291103, '音频小白', 5, '连接很快，音质对得起这个价格，推荐入手。', NULL, 1, '2026-09-20 15:20:00.000'),
(9100000000000000204, 9000000000000000011, 2107757313435291104, '低音控', 2, '用了两周右耳经常断连，重启才好，体验一般。', 'https://img.example.com/earbuds2.jpg', 1, '2026-09-24 20:10:00.000'),
(9100000000000000205, 9000000000000000011, 2107757313435291105, '学生党', 3, '续航太短了，一天一充有点麻烦，音质还行。', NULL, 1, '2026-09-26 09:00:00.000'),
(9100000000000000206, 9000000000000000011, 2107757313435291106, '果粉', 5, '颜值高，白色很好看，降噪够用。', NULL, 1, '2026-09-28 17:30:00.000'),
(9100000000000000207, 9000000000000000011, 2107757313435291107, '好评王', 5, '很好很好很好，特别好用，强烈推荐！', NULL, 1, '2026-09-29 09:00:00.000'),
(9100000000000000208, 9000000000000000011, 2107757313435291108, '好评王', 5, '很好很好很好，特别好用，强烈推荐！', NULL, 1, '2026-09-29 09:00:01.000'),
(9100000000000000209, 9000000000000000011, 2107757313435291109, '好评王', 5, '很好很好很好，特别好用，强烈推荐！', NULL, 1, '2026-09-29 09:00:02.000'),
(9100000000000000210, 9000000000000000011, 2107757313435291110, '独立评测', 2, '做工一般，充电仓盖松动，断连偶发，不推荐。', NULL, 1, '2026-10-01 10:00:00.000')
INSERT INTO `product_review` (review_id, spu_id, user_id, user_name, rating, content, images, is_mock, create_time) VALUES
(9100000000000000301, 9000000000000000012, 2107757313435291201, '棉麻爱好者', 5, '纯棉舒服，版型正，洗了两次没变形。', 'https://img.example.com/tshirt1.jpg', 1, '2026-09-15 13:00:00.000'),
(9100000000000000302, 9000000000000000012, 2107757313435291202, '简约风', 5, '百搭基础款，白色不透，质量可以。', NULL, 1, '2026-09-17 10:40:00.000'),
(9100000000000000303, 9000000000000000012, 2107757313435291203, '在校生', 4, '价格实惠，穿着舒服，就是领口稍微大了一点。', NULL, 1, '2026-09-20 16:00:00.000'),
(9100000000000000304, 9000000000000000012, 2107757313435291204, '奶茶三分甜', 5, '面料亲肤，黑色耐脏，回购了一件。', NULL, 1, '2026-09-23 11:30:00.000'),
(9100000000000000305, 9000000000000000012, 2107757313435291205, '细节控', 2, '洗了一次就有点褪色，白色款泛黄，失望。', 'https://img.example.com/tshirt2.jpg', 1, '2026-09-26 18:20:00.000'),
(9100000000000000306, 9000000000000000012, 2107757313435291206, '路人甲', 5, '发货快，尺码标准，日常穿完全够。', NULL, 1, '2026-09-28 09:10:00.000'),
(9100000000000000307, 9000000000000000012, 2107757313435291207, '怕冷星人', 2, '面料偏薄，缩水比较明显，夏天穿还行冬天不行。', NULL, 1, '2026-10-03 15:50:00.000')
