-- ============================================================
-- 智购 · product-service mock 评价数据（仅 dev profile 执行）
-- 覆盖 3 个测试 SPU：10=运动鞋 11=蓝牙耳机 12=棉T恤
-- 含好评/中评/差评 + 模拟水军特征（重复文本/集中时间/无图五星），
-- 供 AI review_analysis 差评/水军识别规则验证
-- review_id 用固定区间 91000000000000000x 保证幂等
-- ============================================================

-- ── SPU 10 运动鞋（8 条：6 好评 + 1 中评 + 1 差评） ──
ON DUPLICATE KEY UPDATE content = VALUES(content), rating = VALUES(rating);

-- ── SPU 11 蓝牙耳机（10 条：6 好评 + 1 中评 + 2 差评 + 3 条疑似刷评水军特征） ──
ON DUPLICATE KEY UPDATE content = VALUES(content), rating = VALUES(rating);

-- ── SPU 12 棉T恤（7 条：5 好评 + 2 差评） ──
ON DUPLICATE KEY UPDATE content = VALUES(content), rating = VALUES(rating);
